1	package com.example.starter.radio.service;
2	
3	import java.time.Clock;
4	import java.time.LocalDate;
5	import java.time.ZoneOffset;
6	import java.util.List;
7	
8	import com.example.starter.radio.domain.DispensingStatus;
9	import com.example.starter.radio.model.Dispensing;
10	import com.example.starter.radio.model.MotherLiquor;
11	import com.example.starter.radio.model.Nuclide;
12	import com.example.starter.radio.model.Prescription;
13	import com.example.starter.radio.model.ReconciliationLedger;
14	import com.example.starter.radio.repository.CalibratorRepository;
15	import com.example.starter.radio.repository.DispensingRepository;
16	import com.example.starter.radio.repository.MotherLiquorRepository;
17	import com.example.starter.radio.repository.NuclideRepository;
18	import com.example.starter.radio.repository.PrescriptionRepository;
19	import org.springframework.dao.DuplicateKeyException;
20	import org.springframework.stereotype.Service;
21	import org.springframework.transaction.annotation.Transactional;
22	
23	/**
24	 * 分装计算、双人核对与发药勾稽。
25	 * 分装活度按衰变公式推算至给药时刻（UTC），与处方偏差恰 10% 合法、超过 10% 拒绝；
26	 * 发药与母液活度扣减在同一事务内完成；发药完成为终态，重复完成返回幂等成功。
27	 */
28	@Service
29	public class DispensingService {
30	
31	    /** 分装与处方活度偏差阈值：绝对值不超过 10%。 */
32	    public static final double DISPENSE_TOLERANCE = 0.10;
33	
34	    /** 勾稽平衡判定的相对容差（合成数据按 2 的幂衰变可精确复算，容差仅吸收浮点尾差）。 */
35	    private static final double BALANCE_RELATIVE_TOLERANCE = 1e-9;
36	
37	    private final DispensingRepository dispensings;
38	    private final MotherLiquorRepository motherLiquors;
39	    private final PrescriptionRepository prescriptions;
40	    private final CalibratorRepository calibrators;
41	    private final NuclideRepository nuclides;
42	    private final DecayService decay;
43	    private final Clock clock;
44	
45	    public DispensingService(DispensingRepository dispensings,
46	                             MotherLiquorRepository motherLiquors,
47	                             PrescriptionRepository prescriptions,
48	                             CalibratorRepository calibrators,
49	                             NuclideRepository nuclides,
50	                             DecayService decay,
51	                             Clock clock) {
52	        this.dispensings = dispensings;
53	        this.motherLiquors = motherLiquors;
54	        this.prescriptions = prescriptions;
55	        this.calibrators = calibrators;
56	        this.nuclides = nuclides;
57	        this.decay = decay;
58	        this.clock = clock;
59	    }
60	
61	    /**
62	     * 分装计算：幂等；活度计须当日日检通过；母液与处方核素须一致。
63	     */
64	    @Transactional
65	    public Dispensing calculate(String requestId, long motherLiquorId, long prescriptionId, long calibratorId) {
66	        String fingerprint = Fingerprints.of(requestId, motherLiquorId, prescriptionId, calibratorId);
67	        var existing = dispensings.findDispensingByRequestId(requestId);
68	        if (existing.isPresent()) {
69	            return replayOrConflict(existing.get(), fingerprint);
70	        }
71	
72	        MotherLiquor mother = motherLiquors.findById(motherLiquorId)
73	                .orElseThrow(() -> new NotFoundException("母液批次不存在: " + motherLiquorId));
74	        Prescription prescription = prescriptions.findById(prescriptionId)
75	                .orElseThrow(() -> new NotFoundException("处方不存在: " + prescriptionId));
76	        calibrators.findCalibratorById(calibratorId)
77	                .orElseThrow(() -> new NotFoundException("活度计不存在: " + calibratorId));
78	        if (mother.nuclideId() != prescription.nuclideId()) {
79	            throw new BusinessException("母液与处方核素不一致，拒绝分装");
80	        }
81	        Nuclide nuclide = nuclides.findById(mother.nuclideId())
82	                .orElseThrow(() -> new IllegalStateException("核素表缺少记录: " + mother.nuclideId()));
83	
84	        LocalDate today = LocalDate.ofInstant(clock.instant(), ZoneOffset.UTC);
85	        var dailyCheck = calibrators.findDailyCheck(calibratorId, today);
86	        if (dailyCheck.isEmpty() || !dailyCheck.get().passed()) {
87	            throw new BusinessException("活度计当日日检未通过，禁止使用: calibratorId=" + calibratorId);
88	        }
89	
90	        double dispensedAtAdmin = decay.activityAt(mother.initialActivityBq(), mother.referenceTimeEpoch(),
91	                prescription.administrationTimeEpoch(), nuclide.halfLifeSeconds());
92	        double deviation = (dispensedAtAdmin - prescription.prescribedActivityBq())
93	                / prescription.prescribedActivityBq();
94	        boolean legal = Math.abs(deviation) <= DISPENSE_TOLERANCE;
95	
96	        long now = clock.instant().getEpochSecond();
97	        try {
98	            if (legal) {
99	                long id = dispensings.insertDispensing(requestId, fingerprint, motherLiquorId, prescriptionId,
100	                        calibratorId, dispensedAtAdmin, deviation, DispensingStatus.CALCULATED, now);
101	                return dispensings.findDispensingById(id).orElseThrow();
102	            }
103	            long id = dispensings.insertDispensing(requestId, fingerprint, motherLiquorId, prescriptionId,
104	                    calibratorId, null, deviation, DispensingStatus.REJECTED, now);
105	            return dispensings.findDispensingById(id).orElseThrow();
106	        } catch (DuplicateKeyException e) {
107	            return dispensings.findDispensingByRequestId(requestId)
108	                    .map(d -> replayOrConflict(d, fingerprint))
109	                    .orElseThrow(() -> new IllegalStateException("分装幂等记录写入冲突后读取失败", e));
110	        }
111	    }
112	
113	    /**
114	     * 双人核对：两名不同人员先后核对，单人重复核对不生效（409）。
115	     */
116	    @Transactional
117	    public Dispensing check(long dispensingId, String checker) {
118	        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(dispensingId)
119	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
120	        if (dispensing.status() == DispensingStatus.REJECTED
121	                || dispensing.status() == DispensingStatus.DISPENSED) {
122	            throw new BusinessException("分装批次已处于终态，禁止核对: " + dispensing.status());
123	        }
124	        long now = clock.instant().getEpochSecond();
125	        if (dispensing.firstChecker() == null) {
126	            dispensings.updateChecker(dispensingId, "first_checker", checker, now);
127	            dispensings.insertCheck(dispensingId, checker, 1, now);
128	            return dispensings.findDispensingById(dispensingId).orElseThrow();
129	        }
130	        if (dispensing.firstChecker().equals(checker)) {
131	            throw new ConflictException("双人核对须为两名不同人员，单人重复核对不生效: " + checker);
132	        }
133	        if (dispensing.secondChecker() != null) {
134	            throw new BusinessException("双人核对已完成，禁止重复核对");
135	        }
136	        dispensings.updateChecker(dispensingId, "second_checker", checker, now);
137	        dispensings.insertCheck(dispensingId, checker, 2, now);
138	        dispensings.updateStatus(dispensingId, DispensingStatus.CHECKED, now);
139	        return dispensings.findDispensingById(dispensingId).orElseThrow();
140	    }
141	
142	    /**
143	     * 发药：勾稽“母液初始活度＝分装总量＋剩余活度＋衰变残量”，不等拒绝发药；
144	     * 发药与母液剩余活度扣减在同一事务内完成；发药完成为终态，重复完成返回幂等成功。
145	     */
146	    @Transactional
147	    public DispenseResult dispense(String requestId, long dispensingId,
148	                                   double remainingActivityBq, long measuredAtEpoch) {
149	        String fingerprint = Fingerprints.of(requestId, dispensingId, remainingActivityBq, measuredAtEpoch);
150	        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(dispensingId)
151	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
152	
153	        if (dispensing.status() == DispensingStatus.DISPENSED) {
154	            if (requestId.equals(dispensing.dispenseRequestId())) {
155	                if (!fingerprint.equals(dispensing.dispenseFingerprint())) {
156	                    throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复发药: " + requestId);
157	                }
158	                return new DispenseResult(dispensing, dispensings.findLedger(dispensingId).orElse(null), true);
159	            }
160	            // 终态重复完成：幂等成功，不重复扣减库存
161	            return new DispenseResult(dispensing, dispensings.findLedger(dispensingId).orElse(null), true);
162	        }
163	        if (dispensing.status() != DispensingStatus.CHECKED) {
164	            throw new BusinessException("分装批次未完成双人核对或已拒绝，禁止发药: " + dispensing.status());
165	        }
166	
167	        MotherLiquor mother = motherLiquors.findById(dispensing.motherLiquorId()).orElseThrow();
168	        Nuclide nuclide = nuclides.findById(mother.nuclideId()).orElseThrow();
169	        ReconciliationLedger ledger = reconcile(dispensing, mother, nuclide,
170	                remainingActivityBq, measuredAtEpoch);
171	        if (!ledger.balanced()) {
172	            throw new BusinessException(String.format(
173	                    "活度勾稽不平衡，拒绝发药: 初始=%.6f 分装总量=%.6f 剩余=%.6f 衰变残量=%.6f",
174	                    ledger.initialActivityBq(), ledger.dispensedTotalBq(),
175	                    ledger.remainingActivityBq(), ledger.decayResidualBq()));
176	        }
177	
178	        long now = clock.instant().getEpochSecond();
179	        dispensings.insertLedger(ledger, now);
180	        dispensings.markDispensed(dispensingId, requestId, fingerprint, now);
181	        // 发药与母液活度扣减同事务：任一步失败整体回滚
182	        motherLiquors.updateRemaining(mother.id(), remainingActivityBq, measuredAtEpoch);
183	        Dispensing done = dispensings.findDispensingById(dispensingId).orElseThrow();
184	        return new DispenseResult(done, ledger, false);
185	    }
186	
187	    /**
188	     * 批次完成后迟到测量数据只记迟到事件，不改动业务状态。
189	     */
190	    @Transactional
191	    public String recordMeasurement(long dispensingId, String payload) {
192	        Dispensing dispensing = dispensings.findDispensingById(dispensingId)
193	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
194	        if (dispensing.status() != DispensingStatus.DISPENSED) {
195	            throw new BusinessException("分装批次未处于发药完成终态，测量数据应走正常流程: " + dispensing.status());
196	        }
197	        dispensings.insertLateEvent(dispensingId, "LATE_MEASUREMENT", payload,
198	                clock.instant().getEpochSecond());
199	        return "LATE_RECORDED";
200	    }
201	
202	    /**
203	     * 勾稽台账复算：按衰变公式由母液、分装与核对链原始数据重新计算。
204	     * 已发药批次按台账测量时刻复算；未发药批次按当前时刻试算。
205	     */
206	    @Transactional(readOnly = true)
207	    public ReconciliationLedger recompute(long dispensingId) {
208	        Dispensing dispensing = dispensings.findDispensingById(dispensingId)
209	                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
210	        MotherLiquor mother = motherLiquors.findById(dispensing.motherLiquorId()).orElseThrow();
211	        Nuclide nuclide = nuclides.findById(mother.nuclideId()).orElseThrow();
212	        // 已落台账的批次按台账测量时刻复算，保证与台账逐项可比；否则按当前时刻试算
213	        long measuredAt = dispensings.findLedger(dispensingId)
214	                .map(ReconciliationLedger::measuredAtEpoch)
215	                .orElse(dispensing.dispensedAtEpoch() != null
216	                        ? dispensing.dispensedAtEpoch() : clock.instant().getEpochSecond());
217	        double remaining = decay.activityAt(mother.remainingActivityBq(), mother.remainingTimeEpoch(),
218	                measuredAt, nuclide.halfLifeSeconds());
219	        return reconcile(dispensing, mother, nuclide, remaining, measuredAt);
220	    }
221	
222	    /**
223	     * 勾稽：初始活度 = 分装总量 + 剩余活度 + 衰变残量（全部推算至 measuredAtEpoch）。
224	     */
225	    private ReconciliationLedger reconcile(Dispensing dispensing, MotherLiquor mother, Nuclide nuclide,
226	                                           double remainingActivityBq, long measuredAtEpoch) {
227	        long halfLife = nuclide.halfLifeSeconds();
228	        double decayResidual = decay.decayResidual(mother.initialActivityBq(),
229	                mother.referenceTimeEpoch(), measuredAtEpoch, halfLife);
230	        double dispensedTotal = 0.0;
231	        List<Dispensing> actives = dispensings.findActiveByMotherLiquor(mother.id());
232	        for (Dispensing active : actives) {
233	            if (active.dispensedActivityBq() == null) {
234	                continue;
235	            }
236	            Prescription p = prescriptions.findById(active.prescriptionId()).orElseThrow();
237	            dispensedTotal += decay.activityAt(active.dispensedActivityBq(),
238	                    p.administrationTimeEpoch(), measuredAtEpoch, halfLife);
239	        }
240	        double lhs = mother.initialActivityBq();
241	        double rhs = dispensedTotal + remainingActivityBq + decayResidual;
242	        boolean balanced = Math.abs(lhs - rhs) <= BALANCE_RELATIVE_TOLERANCE * Math.max(1.0, Math.abs(lhs));
243	        return new ReconciliationLedger(0L, dispensing.id(), lhs, dispensedTotal,
244	                remainingActivityBq, decayResidual, balanced, measuredAtEpoch);
245	    }
246	
247	    private Dispensing replayOrConflict(Dispensing existing, String fingerprint) {
248	        if (!existing.fingerprint().equals(fingerprint)) {
249	            throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复受理: " + existing.requestId());
250	        }
251	        return existing;
252	    }
253	
254	    /**
255	     * 发药结果。replayed 为 true 表示命中幂等重放或终态重复完成，未发生新的状态变更与扣减。
256	     */
257	    public record DispenseResult(Dispensing dispensing, ReconciliationLedger ledger, boolean replayed) {
258	    }
259	}
