                            + " created_at_epoch, updated_at_epoch) VALUES (?, ?, ?, ?, ?, ?, ?, 'PENDING', ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, requestId);
            ps.setString(2, fingerprint);
            ps.setLong(3, dispensingId);
            ps.setInt(4, baseVersion);
            ps.setLong(5, newAdministrationTimeEpoch);
            ps.setDouble(6, recomputedActivityBq);
            ps.setDouble(7, deviationRatio);
            ps.setLong(8, nowEpoch);
            ps.setLong(9, nowEpoch);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    public Optional<DispensingChange> findChangeById(long id) {
        return jdbc.query("SELECT * FROM dispensing_change WHERE id = ?",
                this::mapChange, id).stream().findFirst();
    }

    /**
     * 复核/作废事务内行锁，串行化并发复核、作废与生效。
     */
    public Optional<DispensingChange> findChangeByIdForUpdate(long id) {
        return jdbc.query("SELECT * FROM dispensing_change WHERE id = ? FOR UPDATE",
                this::mapChange, id).stream().findFirst();
    }

    public Optional<DispensingChange> findChangeByRequestId(String requestId) {
        return jdbc.query("SELECT * FROM dispensing_change WHERE request_id = ?",
                this::mapChange, requestId).stream().findFirst();
    }

    public List<DispensingChange> findChangesByDispensing(long dispensingId) {
        return jdbc.query("SELECT * FROM dispensing_change WHERE dispensing_id = ? ORDER BY id",
                this::mapChange, dispensingId);
    }

    public int updateFirstReviewer(long changeId, String reviewer, long nowEpoch) {
        return jdbc.update("UPDATE dispensing_change SET first_reviewer = ?, updated_at_epoch = ? WHERE id = ?",
                reviewer, nowEpoch, changeId);
    }

    /**
     * 双人复核完成：记录第二复核人并迁移状态；生效时同时写入生效时刻。
     */
    public int completeReview(long changeId, String secondReviewer, ChangeStatus status,
                              Long appliedAtEpoch, long nowEpoch) {
        return jdbc.update(
                "UPDATE dispensing_change SET second_reviewer = ?, status = ?, applied_at_epoch = ?,"
                        + " updated_at_epoch = ? WHERE id = ?",
                secondReviewer, status.name(), appliedAtEpoch, nowEpoch, changeId);
    }

    public int markVoided(long changeId, String voidRequestId, String voidFingerprint, long nowEpoch) {
        return jdbc.update(
                "UPDATE dispensing_change SET status = 'VOIDED', void_request_id = ?, void_fingerprint = ?,"
                        + " updated_at_epoch = ? WHERE id = ?",
                voidRequestId, voidFingerprint, nowEpoch, changeId);
    }

    public long insertReview(String requestId, String fingerprint, long changeId, String reviewer,
                             int reviewSeq, ChangeStatus resultingStatus, long reviewedAtEpoch) {
        KeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO change_review (request_id, fingerprint, change_id, reviewer, review_seq,"
                            + " resulting_status, reviewed_at_epoch) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, requestId);
            ps.setString(2, fingerprint);
            ps.setLong(3, changeId);
            ps.setString(4, reviewer);
            ps.setInt(5, reviewSeq);
            ps.setString(6, resultingStatus.name());
            ps.setLong(7, reviewedAtEpoch);
            return ps;
        }, keys);
        return keys.getKey().longValue();
    }

    public Optional<ChangeReview> findReviewByRequestId(String requestId) {
        return jdbc.query("SELECT * FROM change_review WHERE request_id = ?",
                this::mapReview, requestId).stream().findFirst();
    }

    public List<ChangeReview> findReviews(long changeId) {
        return jdbc.query("SELECT * FROM change_review WHERE change_id = ? ORDER BY review_seq",
                this::mapReview, changeId);
    }

    private DispensingChange mapChange(java.sql.ResultSet rs, int i) throws java.sql.SQLException {
        long appliedAt = rs.getLong("applied_at_epoch");
        Long appliedAtEpoch = rs.wasNull() ? null : appliedAt;
        return new DispensingChange(
                rs.getLong("id"),
                rs.getString("request_id"),
                rs.getString("fingerprint"),
                rs.getLong("dispensing_id"),
                rs.getInt("base_version"),
                rs.getLong("new_administration_time_epoch"),
                rs.getDouble("recomputed_activity_bq"),
                rs.getDouble("deviation_ratio"),
                ChangeStatus.valueOf(rs.getString("status")),
                rs.getString("first_reviewer"),
                rs.getString("second_reviewer"),
                rs.getString("void_request_id"),
                rs.getString("void_fingerprint"),
                appliedAtEpoch);
    }

    private ChangeReview mapReview(java.sql.ResultSet rs, int i) throws java.sql.SQLException {
        return new ChangeReview(
                rs.getLong("id"),
                rs.getString("request_id"),
                rs.getString("fingerprint"),
                rs.getLong("change_id"),
                rs.getString("reviewer"),
                rs.getInt("review_seq"),
                ChangeStatus.valueOf(rs.getString("resulting_status")),
                rs.getLong("reviewed_at_epoch"));
    }
}

