package com.example.starter.radio.service;

import java.time.Clock;
import java.util.List;

import com.example.starter.radio.domain.ChangeStatus;
import com.example.starter.radio.domain.DispensingStatus;
import com.example.starter.radio.model.ChangeReview;
import com.example.starter.radio.model.Dispensing;
import com.example.starter.radio.model.DispensingChange;
import com.example.starter.radio.model.DispensingVersion;
import com.example.starter.radio.model.MotherLiquor;
import com.example.starter.radio.model.Nuclide;
import com.example.starter.radio.model.Prescription;
import com.example.starter.radio.repository.ChangeRepository;
import com.example.starter.radio.repository.DispensingRepository;
import com.example.starter.radio.repository.MotherLiquorRepository;
import com.example.starter.radio.repository.NuclideRepository;
import com.example.starter.radio.repository.PrescriptionRepository;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * 未发药分装的给药时刻变更复核。
 * 变更单形成候选版本，须两名不同人员复核后才同事务生效：替换给药时刻与计算版本、
 * 清除旧双人核对有效性，旧计算与签认永久保留于版本证据与核对链。
 * 候选期间原版本可合法发药；批准与发药竞争只一方先提交（分装行锁串行化）。
 * 仅用于合成数据流程，不用于真实给药决策。
 */
@Service
public class ChangeService {

    /** 库存校验的相对容差，仅吸收浮点尾差。 */
    private static final double INVENTORY_RELATIVE_TOLERANCE = 1e-9;

    private final ChangeRepository changes;
    private final DispensingRepository dispensings;
    private final MotherLiquorRepository motherLiquors;
    private final PrescriptionRepository prescriptions;
    private final NuclideRepository nuclides;
    private final DecayService decay;
    private final Clock clock;

    public ChangeService(ChangeRepository changes,
                         DispensingRepository dispensings,
                         MotherLiquorRepository motherLiquors,
                         PrescriptionRepository prescriptions,
                         NuclideRepository nuclides,
                         DecayService decay,
                         Clock clock) {
        this.changes = changes;
        this.dispensings = dispensings;
        this.motherLiquors = motherLiquors;
        this.prescriptions = prescriptions;
        this.nuclides = nuclides;
        this.decay = decay;
        this.clock = clock;
    }

    /**
     * 提交变更候选：幂等；仅允许已计算未发药分装；expectedVersion 须等于当前计算版本；
     * 新给药时刻须晚于母液参考时刻；按原半衰期与原母液快照重算，仍须满足 ±10% 处方偏差；
     * 库存校验失败或超出偏差不落库、不占幂等键、不扣减母液。
     */
    @Transactional
    public ChangeResult submit(String requestId, long dispensingId, long expectedVersion,
                               long newAdministrationTimeEpoch) {
        String fingerprint = Fingerprints.structured(requestId, dispensingId, expectedVersion,
                newAdministrationTimeEpoch);
        var existing = changes.findChangeByRequestId(requestId);
        if (existing.isPresent()) {
            return new ChangeResult(replayOrConflict(existing.get(), fingerprint), true);
        }

        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(dispensingId)
                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
        if (dispensing.status() == DispensingStatus.DISPENSED
                || dispensing.status() == DispensingStatus.REJECTED) {
            throw new BusinessException("已发药或已拒绝的分装历史绝不重开，禁止变更: " + dispensing.status());
        }
        if (dispensing.version() != expectedVersion) {
            throw new ConflictException(String.format("expectedVersion 与当前计算版本不一致: expected=%d actual=%d",
                    expectedVersion, dispensing.version()));
        }

        MotherLiquor mother = motherLiquors.findById(dispensing.motherLiquorId()).orElseThrow();
        Prescription prescription = prescriptions.findById(dispensing.prescriptionId()).orElseThrow();
        Nuclide nuclide = nuclides.findById(mother.nuclideId()).orElseThrow();
        if (newAdministrationTimeEpoch <= mother.referenceTimeEpoch()) {
            throw new BusinessException("新给药时刻须晚于母液参考时刻: " + newAdministrationTimeEpoch);
        }

        // 按原合成核素半衰期与原母液快照（初始活度@标定时刻）重算目标活度
        double recomputed = decay.activityAt(mother.initialActivityBq(), mother.referenceTimeEpoch(),
                newAdministrationTimeEpoch, nuclide.halfLifeSeconds());
        double deviation = (recomputed - prescription.prescribedActivityBq())
                / prescription.prescribedActivityBq();
        if (Math.abs(deviation) > DispensingService.DISPENSE_TOLERANCE) {
            throw new BusinessException(String.format(
                    "候选重算超出 ±10%% 处方偏差，拒绝提交: recomputed=%.6f deviation=%.6f", recomputed, deviation));
        }
        // 库存校验：目标活度不得超过母液剩余活度推算至新给药时刻的量；失败不扣减母液
        double remainingAtNew = decay.activityAt(mother.remainingActivityBq(), mother.remainingTimeEpoch(),
                newAdministrationTimeEpoch, nuclide.halfLifeSeconds());
        if (recomputed - remainingAtNew
                > INVENTORY_RELATIVE_TOLERANCE * Math.max(1.0, Math.abs(remainingAtNew))) {
            throw new BusinessException(String.format(
                    "库存校验失败，拒绝提交且不扣减母液: recomputed=%.6f remainingAtNew=%.6f",
                    recomputed, remainingAtNew));
        }

        long now = clock.instant().getEpochSecond();
        try {
            long id = changes.insertChange(requestId, fingerprint, dispensingId, dispensing.version(),
                    newAdministrationTimeEpoch, recomputed, deviation, now);
            return new ChangeResult(changes.findChangeById(id).orElseThrow(), false);
        } catch (DuplicateKeyException e) {
            return changes.findChangeByRequestId(requestId)
                    .map(c -> new ChangeResult(replayOrConflict(c, fingerprint), true))
                    .orElseThrow(() -> new IllegalStateException("变更幂等记录写入冲突后读取失败", e));
        }
    }

    /**
     * 双人复核：两名不同人员先后复核；第二人复核时在同事务内尝试生效——
     * 替换给药时刻及计算版本、清除旧双人核对有效性、保留旧计算与签认。
     * 与发药或其他变更竞争失败时变更置为 REJECTED（本次复核仍留痕）。
     */
    @Transactional
    public ReviewResult review(String requestId, long changeId, String reviewer) {
        String fingerprint = Fingerprints.structured(requestId, changeId, reviewer);
        var existingReview = changes.findReviewByRequestId(requestId);
        if (existingReview.isPresent()) {
            ChangeReview review = existingReview.get();
            if (!review.fingerprint().equals(fingerprint)) {
                throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复复核: " + requestId);
            }
            return new ReviewResult(review, changes.findChangeById(review.changeId()).orElseThrow(), true);
        }

        DispensingChange change = changes.findChangeByIdForUpdate(changeId)
                .orElseThrow(() -> new NotFoundException("变更单不存在: " + changeId));
        if (change.status() != ChangeStatus.PENDING) {
            throw new BusinessException("变更单已处于终态，禁止复核: " + change.status());
        }
        if (reviewer.equals(change.firstReviewer())) {
            throw new ConflictException("双人复核须为两名不同人员，单人重复复核不生效: " + reviewer);
        }

        long now = clock.instant().getEpochSecond();
        if (change.firstReviewer() == null) {
            changes.updateFirstReviewer(changeId, reviewer, now);
            long reviewId = changes.insertReview(requestId, fingerprint, changeId, reviewer, 1,
                    ChangeStatus.PENDING, now);
            return new ReviewResult(changes.findReviewByRequestId(requestId).orElseThrow(),
                    changes.findChangeById(changeId).orElseThrow(), false);
        }

        // 第二人复核：与发药/其他变更竞争，分装行锁串行化，只一方先提交
        Dispensing dispensing = dispensings.findDispensingByIdForUpdate(change.dispensingId()).orElseThrow();
        if (dispensing.status() == DispensingStatus.DISPENSED) {
            // 发药先成：变更拒绝，复核留痕，不改动分装与库存
            changes.completeReview(changeId, reviewer, ChangeStatus.REJECTED, null, now);
            changes.insertReview(requestId, fingerprint, changeId, reviewer, 2, ChangeStatus.REJECTED, now);
            return new ReviewResult(changes.findReviewByRequestId(requestId).orElseThrow(),
                    changes.findChangeById(changeId).orElseThrow(), false);
        }
        if (dispensing.version() != change.baseVersion()) {
            // 其他变更先生效：本变更基于旧版本，拒绝
            changes.completeReview(changeId, reviewer, ChangeStatus.REJECTED, null, now);
            changes.insertReview(requestId, fingerprint, changeId, reviewer, 2, ChangeStatus.REJECTED, now);
            return new ReviewResult(changes.findReviewByRequestId(requestId).orElseThrow(),
                    changes.findChangeById(changeId).orElseThrow(), false);
        }

        // 生效：同事务替换给药时刻及计算版本、清除旧双人核对有效性；旧计算与签认保留于版本证据
        int newVersion = dispensing.version() + 1;
        dispensings.applyChange(dispensing.id(), change.newAdministrationTimeEpoch(),
                change.recomputedActivityBq(), change.deviationRatio(), newVersion, now);
        dispensings.insertVersion(dispensing.id(), newVersion, change.newAdministrationTimeEpoch(),
                change.recomputedActivityBq(), change.deviationRatio(), change.id(), now);
        changes.completeReview(changeId, reviewer, ChangeStatus.APPROVED, now, now);
        changes.insertReview(requestId, fingerprint, changeId, reviewer, 2, ChangeStatus.APPROVED, now);
        return new ReviewResult(changes.findReviewByRequestId(requestId).orElseThrow(),
                changes.findChangeById(changeId).orElseThrow(), false);
    }

    /**
     * 作废候选变更：幂等；仅 PENDING 可作废，已生效/已拒绝/已作废为终态。
     */
    @Transactional
    public ChangeResult voidChange(String requestId, long changeId) {
        String fingerprint = Fingerprints.structured(requestId, changeId);
        DispensingChange change = changes.findChangeByIdForUpdate(changeId)
                .orElseThrow(() -> new NotFoundException("变更单不存在: " + changeId));
        if (requestId.equals(change.voidRequestId())) {
            if (!fingerprint.equals(change.voidFingerprint())) {
                throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复作废: " + requestId);
            }
            return new ChangeResult(change, true);
        }
        if (change.status() != ChangeStatus.PENDING) {
            throw new BusinessException("变更单已处于终态，禁止作废: " + change.status());
        }
        changes.markVoided(changeId, requestId, fingerprint, clock.instant().getEpochSecond());
        return new ChangeResult(changes.findChangeById(changeId).orElseThrow(), false);
    }

    /**
     * 变更单详情（含双人复核链）。
     */
    @Transactional(readOnly = true)
    public ChangeDetail getChange(long changeId) {
        DispensingChange change = changes.findChangeById(changeId)
                .orElseThrow(() -> new NotFoundException("变更单不存在: " + changeId));
        return new ChangeDetail(change, changes.findReviews(changeId));
    }

    /**
     * 分装的全部变更单。
     */
    @Transactional(readOnly = true)
    public List<DispensingChange> listChanges(long dispensingId) {
        dispensings.findDispensingById(dispensingId)
                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
        return changes.findChangesByDispensing(dispensingId);
    }

    /**
     * 版本计算证据：各计算版本的给药时刻、活度、偏差与签认。
     */
    @Transactional(readOnly = true)
    public List<DispensingVersion> listVersions(long dispensingId) {
        dispensings.findDispensingById(dispensingId)
                .orElseThrow(() -> new NotFoundException("分装批次不存在: " + dispensingId));
        return dispensings.findVersions(dispensingId);
    }

    private DispensingChange replayOrConflict(DispensingChange existing, String fingerprint) {
        if (!existing.fingerprint().equals(fingerprint)) {
            throw new ConflictException("相同 requestId 但业务字段不一致，拒绝重复受理: " + existing.requestId());
        }
        return existing;
    }

    /**
     * 变更提交/作废结果。replayed 为 true 表示命中幂等重放，未发生新的状态变更。
     */
    public record ChangeResult(DispensingChange change, boolean replayed) {
    }

    /**
     * 复核结果。review.resultingStatus 为本次复核冻结结果；replayed 为 true 表示幂等重放。
     */
    public record ReviewResult(ChangeReview review, DispensingChange change, boolean replayed) {
    }

    /**
     * 变更单详情：变更单与双人复核链。
     */
    public record ChangeDetail(DispensingChange change, List<ChangeReview> reviews) {
    }
}

