    /**
     * 给药时刻变更提交请求：requestId 幂等；expectedVersion 须等于分装当前计算版本；
     * newAdministrationTime 为新的给药时刻（ISO-8601 UTC），须晚于母液参考时刻。
     */
    public record SubmitChangeRequest(
            @NotBlank String requestId,
            @NotNull Long dispensingId,
            @NotNull Long expectedVersion,
            @NotBlank String newAdministrationTime) {

        public long newAdministrationTimeEpoch() {
            return Instant.parse(newAdministrationTime).getEpochSecond();
        }
    }

    /** 变更复核请求：requestId 幂等；两名复核人员必须不同。 */
    public record ReviewChangeRequest(
            @NotBlank String requestId,
