/**
 * 勾稽台账复算：按衰变公式由原始数据重新计算，用于核对已存台账。
 */
@GetMapping("/dispensings/{id}/reconciliation")
public Map<String, Object> recomputeReconciliation(@PathVariable long id) {
    return ledgerView(dispensingService.recompute(id));
}

/**
 * 提交给药时刻变更候选：仅已计算未发药分装；重算仍须满足 ±10% 处方偏差。
 */
@PostMapping("/changes")
public Map<String, Object> submitChange(@Valid @RequestBody RadioApiDtos.SubmitChangeRequest req) {
    ChangeService.ChangeResult result = changeService.submit(req.requestId(), req.dispensingId(),
            req.expectedVersion(), req.newAdministrationTimeEpoch());
    Map<String, Object> view = changeView(result.change());
    view.put("replayed", result.replayed());
    return view;
}

/**
 * 变更复核：两名不同人员先后复核；第二人复核通过则同事务生效。
 * 生效竞争失败（已发药或版本被抢先）时变更置为 REJECTED，返回 422 与冻结证据。
 */
@PostMapping("/changes/{id}/reviews")
public ResponseEntity<?> reviewChange(@PathVariable long id,
                                      @Valid @RequestBody RadioApiDtos.ReviewChangeRequest req) {
    ChangeService.ReviewResult result = changeService.review(req.requestId(), id, req.reviewer());
    Map<String, Object> view = new LinkedHashMap<>();
    view.put("changeId", result.change().id());
    view.put("dispensingId", result.change().dispensingId());
    view.put("reviewer", result.review().reviewer());
    view.put("reviewSeq", result.review().reviewSeq());
    view.put("resultingStatus", result.review().resultingStatus().name());
    view.put("status", result.change().status().name());
    view.put("replayed", result.replayed());
    if (result.change().status() == ChangeStatus.APPROVED) {
        view.put("appliedAt", result.change().appliedAtEpoch() == null ? null
                : Instant.ofEpochSecond(result.change().appliedAtEpoch()).toString());
    }
    if (result.review().resultingStatus() == ChangeStatus.REJECTED) {
        view.put("error", "变更生效竞争失败，已拒绝: 分装已发药或计算版本已被其他变更抢先");
        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY).body(view);
    }
    return ResponseEntity.ok(view);
}

/**
 * 作废候选变更：仅 PENDING 可作废。
 */
@PostMapping("/changes/{id}/void")
public Map<String, Object> voidChange(@PathVariable long id,
                                      @Valid @RequestBody RadioApiDtos.VoidChangeRequest req) {
    ChangeService.ChangeResult result = changeService.voidChange(req.requestId(), id);
    Map<String, Object> view = changeView(result.change());
    view.put("replayed", result.replayed());
    return view;
}

/**
 * 变更单详情（含双人复核链）。
 */
@GetMapping("/changes/{id}")
public Map<String, Object> getChange(@PathVariable long id) {
    ChangeService.ChangeDetail detail = changeService.getChange(id);
    Map<String, Object> view = changeView(detail.change());
    view.put("reviews", detail.reviews().stream().map(this::reviewView).toList());
    return view;
}

/**
 * 分装的全部变更单。
 */
@GetMapping("/dispensings/{id}/changes")
public List<Map<String, Object>> listChanges(@PathVariable long id) {
    return changeService.listChanges(id).stream().map(this::changeView).toList();
}

/**
 * 版本计算证据：各计算版本的给药时刻、活度、偏差与签认；旧版本永久保留。
 */
@GetMapping("/dispensings/{id}/versions")
public List<Map<String, Object>> listVersions(@PathVariable long id) {
    return changeService.listVersions(id).stream().map(this::versionView).toList();
}

private Map<String, Object> changeView(DispensingChange c) {
    Map<String, Object> view = new LinkedHashMap<>();
    view.put("id", c.id());
    view.put("requestId", c.requestId());
