 * 未发药分装给药时刻变更复核的 H2 集成测试。
 * 合成数据：SYN-1H 半衰期 3600s；母液 2200 Bq @ T0；处方 550 Bq @ T0+7200s（衰变后恰 550 Bq，偏差 0）；
 * 新给药时刻 T0+7000s，重算活度 2200*2^(-7000/3600) ≈ 571.59 Bq，偏差约 +3.93%，合法。
 */
class ChangeServiceTest extends IntegrationTestBase {

    private static final long ADMIN_EPOCH = T0.getEpochSecond() + 7200L;
    private static final long NEW_ADMIN_EPOCH = T0.getEpochSecond() + 7000L;
    private static final double RECOMPUTED = 2200.0 * Math.pow(0.5, 7000.0 / 3600.0);
    private static final double RECOMPUTED_DEVIATION = (RECOMPUTED - 550.0) / 550.0;

    @Autowired
    private ChangeService changeService;

    @Autowired
    private DispensingService dispensingService;

    @Autowired
    private CalibratorService calibratorService;

    @Autowired
    private RegistrationService registrationService;

    @Autowired
    private DispensingRepository dispensings;

    @Autowired
    private MotherLiquorRepository motherLiquors;

    @Test
    void submitCreatesPendingCandidateWithoutTouchingDispensingOrMother() {
        Fixture f = newCheckedFixture();
        ChangeService.ChangeResult result = changeService.submit(unique("REQ"), f.dispensingId, 1L,
                NEW_ADMIN_EPOCH);
        assertThat(result.replayed()).isFalse();
        DispensingChange change = result.change();
        assertThat(change.status()).isEqualTo(ChangeStatus.PENDING);
        assertThat(change.baseVersion()).isEqualTo(1);
        assertThat(change.newAdministrationTimeEpoch()).isEqualTo(NEW_ADMIN_EPOCH);
        assertThat(change.recomputedActivityBq()).isEqualTo(RECOMPUTED);
        assertThat(change.deviationRatio()).isEqualTo(RECOMPUTED_DEVIATION);
        // 候选期间有效分装不变：版本、给药时刻、双人核对签认保持
        Dispensing dispensing = dispensings.findDispensingById(f.dispensingId).orElseThrow();
        assertThat(dispensing.version()).isEqualTo(1);
        assertThat(dispensing.administrationTimeEpoch()).isEqualTo(ADMIN_EPOCH);
        assertThat(dispensing.status()).isEqualTo(DispensingStatus.CHECKED);
        assertThat(dispensing.firstChecker()).isEqualTo("alice");
        assertThat(dispensing.secondChecker()).isEqualTo("bob");
        // 不扣减母液
        assertThat(motherLiquors.findById(f.motherId).orElseThrow().remainingActivityBq()).isEqualTo(2200.0);
    }

    @Test
    void submitRejectsInvalidTargetsAndFailuresDoNotOccupyKey() {
        Fixture f = newCheckedFixture();
        // 对象不存在 → 404
        assertThatThrownBy(() -> changeService.submit(unique("REQ"), 999999L, 1L, NEW_ADMIN_EPOCH))
                .isInstanceOf(NotFoundException.class);
        // expectedVersion 与当前版本不一致 → 409
        assertThatThrownBy(() -> changeService.submit(unique("REQ"), f.dispensingId, 2L, NEW_ADMIN_EPOCH))
                .isInstanceOf(ConflictException.class);
        // 新给药时刻不晚于母液参考时刻 → 422
        assertThatThrownBy(() -> changeService.submit(unique("REQ"), f.dispensingId, 1L, T0.getEpochSecond()))
                .isInstanceOf(BusinessException.class)
                .hasMessageContaining("晚于母液参考时刻");
        // 候选超出 ±10% 偏差（T0+3600 重算 1100 Bq，偏差 +100%）→ 422，且失败不占键
        String requestId = unique("REQ");
        assertThatThrownBy(() -> changeService.submit(requestId, f.dispensingId, 1L,
                T0.getEpochSecond() + 3600L))
                .isInstanceOf(BusinessException.class)
                .hasMessageContaining("偏差");
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM dispensing_change", Integer.class)).isZero();
        // 同键换合法参数可正常提交
        ChangeService.ChangeResult retry = changeService.submit(requestId, f.dispensingId, 1L, NEW_ADMIN_EPOCH);
        assertThat(retry.change().status()).isEqualTo(ChangeStatus.PENDING);
    }

    @Test
    void submitOnDispensedHistoryNeverReopens() {
        Fixture f = newCheckedFixture();
        dispensingService.dispense(unique("REQ"), f.dispensingId, 0.0, ADMIN_EPOCH);
        assertThatThrownBy(() -> changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH))
                .isInstanceOf(BusinessException.class)
                .hasMessageContaining("绝不重开");
    }

    @Test
    void inventoryCheckFailureDoesNotDeductMotherLiquor() {
        Fixture f = newCheckedFixture();
        // 另一分装发药把母液剩余扣至 0
        Dispensing other = dispensingService.calculate(unique("REQ"), f.motherId, f.prescriptionId,
                f.calibratorId);
        dispensingService.check(other.id(), "carol");
        dispensingService.check(other.id(), "dave");
        dispensingService.dispense(unique("REQ"), other.id(), 550.0, ADMIN_EPOCH);
        assertThat(motherLiquors.findById(f.motherId).orElseThrow().remainingActivityBq()).isEqualTo(550.0);
        // 剩余 550 @ T0+7200 推算至 T0+7000 高于 550，但仍低于重算目标 571.59 → 库存校验失败
        String requestId = unique("REQ");
        assertThatThrownBy(() -> changeService.submit(requestId, f.dispensingId, 1L, NEW_ADMIN_EPOCH))
                .isInstanceOf(BusinessException.class)
                .hasMessageContaining("库存");
        // 不扣减母液、不落库、不占键
        assertThat(motherLiquors.findById(f.motherId).orElseThrow().remainingActivityBq()).isEqualTo(550.0);
        assertThat(jdbc.queryForObject("SELECT COUNT(*) FROM dispensing_change", Integer.class)).isZero();
    }

    @Test
    void dualReviewApprovesAndRotatesVersionKeepingOldEvidence() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();

        ChangeService.ReviewResult first = changeService.review(unique("REQ"), changeId, "carol");
        assertThat(first.review().resultingStatus()).isEqualTo(ChangeStatus.PENDING);
        assertThat(first.change().firstReviewer()).isEqualTo("carol");
        assertThat(first.change().status()).isEqualTo(ChangeStatus.PENDING);
        // 单人重复复核不生效 → 409
        assertThatThrownBy(() -> changeService.review(unique("REQ"), changeId, "carol"))
                .isInstanceOf(ConflictException.class);

        ChangeService.ReviewResult second = changeService.review(unique("REQ"), changeId, "dave");
        assertThat(second.review().resultingStatus()).isEqualTo(ChangeStatus.APPROVED);
        assertThat(second.change().status()).isEqualTo(ChangeStatus.APPROVED);
        assertThat(second.change().appliedAtEpoch()).isNotNull();

        // 生效：给药时刻与计算版本替换、旧双人核对有效性清除
        Dispensing dispensing = dispensings.findDispensingById(f.dispensingId).orElseThrow();
        assertThat(dispensing.version()).isEqualTo(2);
        assertThat(dispensing.administrationTimeEpoch()).isEqualTo(NEW_ADMIN_EPOCH);
        assertThat(dispensing.dispensedActivityBq()).isEqualTo(RECOMPUTED);
        assertThat(dispensing.status()).isEqualTo(DispensingStatus.CALCULATED);
        assertThat(dispensing.firstChecker()).isNull();
        assertThat(dispensing.secondChecker()).isNull();

        // 旧计算与签认保留：版本证据 v1（含 alice/bob 签认）与 v2（来源变更单）
        List<DispensingVersion> versions = changeService.listVersions(f.dispensingId);
        assertThat(versions).hasSize(2);
        DispensingVersion v1 = versions.get(0);
        assertThat(v1.version()).isEqualTo(1);
        assertThat(v1.administrationTimeEpoch()).isEqualTo(ADMIN_EPOCH);
        assertThat(v1.dispensedActivityBq()).isEqualTo(550.0);
        assertThat(v1.changeId()).isNull();
        assertThat(v1.firstChecker()).isEqualTo("alice");
        assertThat(v1.secondChecker()).isEqualTo("bob");
        DispensingVersion v2 = versions.get(1);
        assertThat(v2.version()).isEqualTo(2);
        assertThat(v2.administrationTimeEpoch()).isEqualTo(NEW_ADMIN_EPOCH);
        assertThat(v2.dispensedActivityBq()).isEqualTo(RECOMPUTED);
        assertThat(v2.changeId()).isEqualTo(changeId);
        // 旧核对链签认保留于 dispensing_check（版本 1）
        assertThat(jdbc.queryForObject(
                "SELECT COUNT(*) FROM dispensing_check WHERE dispensing_id = ? AND version = 1",
                Integer.class, f.dispensingId)).isEqualTo(2);
    }

    @Test
    void oldSignoffsNotReusedAndNewVersionMustBeRecheckedBeforeDispense() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        changeService.review(unique("REQ"), changeId, "carol");
        changeService.review(unique("REQ"), changeId, "dave");

        // 旧签认不得复用：未重新核对直接发药 → 422
        assertThatThrownBy(() -> dispensingService.dispense(unique("REQ"), f.dispensingId, 0.0, NEW_ADMIN_EPOCH))
                .isInstanceOf(BusinessException.class);
        // 重新完成两名不同人员核对新版本后发药成功：2200 = 571.59 + 0 + (2200-571.59)
        dispensingService.check(f.dispensingId, "alice");
        dispensingService.check(f.dispensingId, "bob");
        DispensingService.DispenseResult result = dispensingService.dispense(unique("REQ"), f.dispensingId,
                0.0, NEW_ADMIN_EPOCH);
        assertThat(result.dispensing().status()).isEqualTo(DispensingStatus.DISPENSED);
        assertThat(result.ledger().balanced()).isTrue();
        assertThat(result.ledger().dispensedTotalBq()).isEqualTo(RECOMPUTED);
        // 核对链包含两个版本的签认
        assertThat(jdbc.queryForObject(
                "SELECT COUNT(*) FROM dispensing_check WHERE dispensing_id = ? AND version = 2",
                Integer.class, f.dispensingId)).isEqualTo(2);
    }

    @Test
    void originalVersionCanDispenseDuringCandidateAndChangeThenRejected() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        changeService.review(unique("REQ"), changeId, "carol");
        // 候选期间原版本合法发药
        DispensingService.DispenseResult dispensed = dispensingService.dispense(unique("REQ"), f.dispensingId,
                0.0, ADMIN_EPOCH);
        assertThat(dispensed.dispensing().status()).isEqualTo(DispensingStatus.DISPENSED);
        // 发药先成：变更拒绝，复核留痕
        ChangeService.ReviewResult second = changeService.review(unique("REQ"), changeId, "dave");
        assertThat(second.review().resultingStatus()).isEqualTo(ChangeStatus.REJECTED);
        assertThat(second.change().status()).isEqualTo(ChangeStatus.REJECTED);
        assertThat(dispensings.findDispensingById(f.dispensingId).orElseThrow().status())
                .isEqualTo(DispensingStatus.DISPENSED);
    }

    @Test
    void secondChangeRejectedWhenOtherChangeAppliedFirst() {
        Fixture f = newCheckedFixture();
        long winner = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH).change().id();
        long loser = changeService.submit(unique("REQ"), f.dispensingId, 1L,
                T0.getEpochSecond() + 7100L).change().id();
        changeService.review(unique("REQ"), winner, "carol");
        changeService.review(unique("REQ"), winner, "dave");
        assertThat(changeService.getChange(winner).change().status()).isEqualTo(ChangeStatus.APPROVED);
        // 另一变更基于旧版本，生效竞争失败 → REJECTED
        changeService.review(unique("REQ"), loser, "carol");
        ChangeService.ReviewResult lost = changeService.review(unique("REQ"), loser, "dave");
        assertThat(lost.review().resultingStatus()).isEqualTo(ChangeStatus.REJECTED);
        assertThat(changeService.getChange(loser).change().status()).isEqualTo(ChangeStatus.REJECTED);
        assertThat(dispensings.findDispensingById(f.dispensingId).orElseThrow().version()).isEqualTo(2);
    }

    @Test
    void concurrentDispenseAndApprovalExactlyOneWins() throws Exception {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        changeService.review(unique("REQ"), changeId, "carol");

        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch ready = new CountDownLatch(2);
        CountDownLatch start = new CountDownLatch(1);
        try {
            Future<Object> dispenseFuture = pool.submit(() -> {
                ready.countDown();
                start.await();
                try {
                    return dispensingService.dispense(unique("REQ"), f.dispensingId, 0.0, ADMIN_EPOCH);
                } catch (RuntimeException e) {
                    return e;
                }
            });
            Future<ChangeService.ReviewResult> reviewFuture = pool.submit(() -> {
                ready.countDown();
                start.await();
                return changeService.review(unique("REQ"), changeId, "dave");
            });
            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
            start.countDown();
            Object dispenseOutcome = dispenseFuture.get(30, TimeUnit.SECONDS);
            ChangeService.ReviewResult reviewOutcome = reviewFuture.get(30, TimeUnit.SECONDS);

            DispensingChange change = changeService.getChange(changeId).change();
            Dispensing dispensing = dispensings.findDispensingById(f.dispensingId).orElseThrow();
            if (dispenseOutcome instanceof DispensingService.DispenseResult) {
                // 发药先成：变更拒绝
                assertThat(change.status()).isEqualTo(ChangeStatus.REJECTED);
                assertThat(reviewOutcome.review().resultingStatus()).isEqualTo(ChangeStatus.REJECTED);
                assertThat(dispensing.status()).isEqualTo(DispensingStatus.DISPENSED);
                assertThat(dispensing.version()).isEqualTo(1);
            } else {
                // 变更先成：旧版本发药拒绝，不能用新时刻搭旧活度
                assertThat(dispenseOutcome).isInstanceOf(BusinessException.class);
                assertThat(change.status()).isEqualTo(ChangeStatus.APPROVED);
                assertThat(dispensing.status()).isEqualTo(DispensingStatus.CALCULATED);
                assertThat(dispensing.version()).isEqualTo(2);
                assertThat(dispensing.administrationTimeEpoch()).isEqualTo(NEW_ADMIN_EPOCH);
            }
        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    void submitIdempotencyReplaysFrozenResultDespiteMotherChanges() {
        Fixture f = newCheckedFixture();
        String requestId = unique("REQ");
        ChangeService.ChangeResult first = changeService.submit(requestId, f.dispensingId, 1L, NEW_ADMIN_EPOCH);
        // 同键同参：重放首次冻结结果
        ChangeService.ChangeResult replay = changeService.submit(requestId, f.dispensingId, 1L, NEW_ADMIN_EPOCH);
        assertThat(replay.replayed()).isTrue();
        assertThat(replay.change().id()).isEqualTo(first.change().id());
        // 同键异参 → 409
        assertThatThrownBy(() -> changeService.submit(requestId, f.dispensingId, 1L,
                T0.getEpochSecond() + 7100L))
                .isInstanceOf(ConflictException.class);
        // 母液剩余量随后变化不影响已冻结的重放结果
        motherLiquors.updateRemaining(f.motherId, 100.0, T0.getEpochSecond());
        ChangeService.ChangeResult afterMotherChange = changeService.submit(requestId, f.dispensingId, 1L,
                NEW_ADMIN_EPOCH);
        assertThat(afterMotherChange.replayed()).isTrue();
        assertThat(afterMotherChange.change().recomputedActivityBq()).isEqualTo(RECOMPUTED);
    }

    @Test
    void reviewIdempotencyAndSeparatorInReviewerName() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        // 合法文本含分隔符 '|' 的复核人可正常复核
        String requestId = unique("REQ");
        ChangeService.ReviewResult first = changeService.review(requestId, changeId, "carol|night-shift");
        assertThat(first.change().firstReviewer()).isEqualTo("carol|night-shift");
        // 同键同参重放：返回首次冻结结果
        ChangeService.ReviewResult replay = changeService.review(requestId, changeId, "carol|night-shift");
        assertThat(replay.replayed()).isTrue();
        assertThat(replay.review().resultingStatus()).isEqualTo(ChangeStatus.PENDING);
        // 同键异参（含分隔符前缀相同的不同复核人）→ 409
        assertThatThrownBy(() -> changeService.review(requestId, changeId, "carol"))
                .isInstanceOf(ConflictException.class);
    }

    @Test
    void voidChangeOnlyWhilePending() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        String voidRequest = unique("REQ");
        ChangeService.ChangeResult voided = changeService.voidChange(voidRequest, changeId);
        assertThat(voided.change().status()).isEqualTo(ChangeStatus.VOIDED);
        // 同键重放
        assertThat(changeService.voidChange(voidRequest, changeId).replayed()).isTrue();
        // 异键重复作废 → 422；已作废禁止复核 → 422
        assertThatThrownBy(() -> changeService.voidChange(unique("REQ"), changeId))
                .isInstanceOf(BusinessException.class);
        assertThatThrownBy(() -> changeService.review(unique("REQ"), changeId, "carol"))
                .isInstanceOf(BusinessException.class);
        // 作废后分装未受影响，仍可正常发药流程
        Dispensing dispensing = dispensings.findDispensingById(f.dispensingId).orElseThrow();
        assertThat(dispensing.status()).isEqualTo(DispensingStatus.CHECKED);
        assertThat(dispensing.version()).isEqualTo(1);
    }

    @Test
    void approvedChangeCannotBeVoidedAndTerminalChangeCannotBeReviewed() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        changeService.review(unique("REQ"), changeId, "carol");
        changeService.review(unique("REQ"), changeId, "dave");
        assertThatThrownBy(() -> changeService.voidChange(unique("REQ"), changeId))
                .isInstanceOf(BusinessException.class);
        assertThatThrownBy(() -> changeService.review(unique("REQ"), changeId, "ellen"))
                .isInstanceOf(BusinessException.class);
    }

    /** 构造母液 2200 Bq@T0、处方 550 Bq@T0+7200、已完成双人核对的批次夹具。 */
    private Fixture newCheckedFixture() {
        long calibratorId = registrationService.registerCalibrator(unique("CAL"), "合成活度计");
        calibratorService.dailyCheck(unique("REQ"), calibratorId, CHECK_DATE, 1000.0, 1000.0);
        MotherLiquor mother = registrationService.registerMotherLiquor(unique("ML"), "SYN-1H",
                2200.0, T0.getEpochSecond());
        Prescription prescription = registrationService.registerPrescription(unique("RX"), "SYN-1H",
                550.0, ADMIN_EPOCH);
        Dispensing d = dispensingService.calculate(unique("REQ"), mother.id(), prescription.id(), calibratorId);
        assertThat(d.dispensedActivityBq()).isEqualTo(550.0);
        dispensingService.check(d.id(), "alice");
        dispensingService.check(d.id(), "bob");
        return new Fixture(mother.id(), prescription.id(), calibratorId, d.id());
    }

    private record Fixture(long motherId, long prescriptionId, long calibratorId, long dispensingId) {
    }
}

