        assertThat(dispensing.administrationTimeEpoch()).isEqualTo(NEW_ADMIN_EPOCH);
        assertThat(dispensing.dispensedActivityBq()).isEqualTo(RECOMPUTED);
        assertThat(dispensing.status()).isEqualTo(DispensingStatus.CALCULATED);
        assertThat(dispensing.firstChecker()).isNull();
        assertThat(dispensing.secondChecker()).isNull();

        // 旧计算与签认保留：版本证据 v1（含 alice/bob 签认）与 v2（来源变更单）
        List<DispensingVersion> versions = changeService.listVersions(f.dispensingId);
        assertThat(versions).hasSize(2);
