        assertThat(v1.version()).isEqualTo(1);
        assertThat(v1.administrationTimeEpoch()).isEqualTo(ADMIN_EPOCH);
        assertThat(v1.dispensedActivityBq()).isEqualTo(550.0);
        assertThat(v1.changeId()).isNull();
        assertThat(v1.firstChecker()).isEqualTo("alice");
        assertThat(v1.secondChecker()).isEqualTo("bob");
        DispensingVersion v2 = versions.get(1);
        assertThat(v2.version()).isEqualTo(2);
        assertThat(v2.administrationTimeEpoch()).isEqualTo(NEW_ADMIN_EPOCH);
        assertThat(v2.dispensedActivityBq()).isEqualTo(RECOMPUTED);
        assertThat(v2.changeId()).isEqualTo(changeId);
        // 旧核对链签认保留于 dispensing_check（版本 1）
        assertThat(jdbc.queryForObject(
                "SELECT COUNT(*) FROM dispensing_check WHERE dispensing_id = ? AND version = 1",
                Integer.class, f.dispensingId)).isEqualTo(2);
    }

