    @Test
    void secondChangeRejectedWhenOtherChangeAppliedFirst() {
        Fixture f = newCheckedFixture();
        long winner = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH).change().id();
        long loser = changeService.submit(unique("REQ"), f.dispensingId, 1L,
                T0.getEpochSecond() + 7100L).change().id();
        changeService.review(unique("REQ"), winner, "carol");
        changeService.review(unique("REQ"), winner, "dave");
        assertThat(changeService.getChange(winner).change().status()).isEqualTo(ChangeStatus.APPROVED);
        // 另一变更基于旧版本，生效竞争失败 → REJECTED
        changeService.review(unique("REQ"), loser, "carol");
        ChangeService.ReviewResult lost = changeService.review(unique("REQ"), loser, "dave");
        assertThat(lost.review().resultingStatus()).isEqualTo(ChangeStatus.REJECTED);
        assertThat(changeService.getChange(loser).change().status()).isEqualTo(ChangeStatus.REJECTED);
        assertThat(dispensings.findDispensingById(f.dispensingId).orElseThrow().version()).isEqualTo(2);
    }

    @Test
    void concurrentDispenseAndApprovalExactlyOneWins() throws Exception {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        changeService.review(unique("REQ"), changeId, "carol");

        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch ready = new CountDownLatch(2);
        CountDownLatch start = new CountDownLatch(1);
        try {
            Future<Object> dispenseFuture = pool.submit(() -> {
                ready.countDown();
                start.await();
                try {
                    return dispensingService.dispense(unique("REQ"), f.dispensingId, 0.0, ADMIN_EPOCH);
                } catch (RuntimeException e) {
                    return e;
                }
            });
            Future<ChangeService.ReviewResult> reviewFuture = pool.submit(() -> {
                ready.countDown();
                start.await();
                return changeService.review(unique("REQ"), changeId, "dave");
            });
            assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
            start.countDown();
            Object dispenseOutcome = dispenseFuture.get(30, TimeUnit.SECONDS);
            ChangeService.ReviewResult reviewOutcome = reviewFuture.get(30, TimeUnit.SECONDS);

            DispensingChange change = changeService.getChange(changeId).change();
            Dispensing dispensing = dispensings.findDispensingById(f.dispensingId).orElseThrow();
            if (dispenseOutcome instanceof DispensingService.DispenseResult) {
                // 发药先成：变更拒绝
                assertThat(change.status()).isEqualTo(ChangeStatus.REJECTED);
                assertThat(reviewOutcome.review().resultingStatus()).isEqualTo(ChangeStatus.REJECTED);
                assertThat(dispensing.status()).isEqualTo(DispensingStatus.DISPENSED);
                assertThat(dispensing.version()).isEqualTo(1);
            } else {
                // 变更先成：旧版本发药拒绝，不能用新时刻搭旧活度
                assertThat(dispenseOutcome).isInstanceOf(BusinessException.class);
                assertThat(change.status()).isEqualTo(ChangeStatus.APPROVED);
                assertThat(dispensing.status()).isEqualTo(DispensingStatus.CALCULATED);
                assertThat(dispensing.version()).isEqualTo(2);
                assertThat(dispensing.administrationTimeEpoch()).isEqualTo(NEW_ADMIN_EPOCH);
            }
        } finally {
            pool.shutdownNow();
        }
    }

    @Test
    void submitIdempotencyReplaysFrozenResultDespiteMotherChanges() {
        Fixture f = newCheckedFixture();
        String requestId = unique("REQ");
        ChangeService.ChangeResult first = changeService.submit(requestId, f.dispensingId, 1L, NEW_ADMIN_EPOCH);
        // 同键同参：重放首次冻结结果
        ChangeService.ChangeResult replay = changeService.submit(requestId, f.dispensingId, 1L, NEW_ADMIN_EPOCH);
        assertThat(replay.replayed()).isTrue();
        assertThat(replay.change().id()).isEqualTo(first.change().id());
        // 同键异参 → 409
        assertThatThrownBy(() -> changeService.submit(requestId, f.dispensingId, 1L,
                T0.getEpochSecond() + 7100L))
                .isInstanceOf(ConflictException.class);
        // 母液剩余量随后变化不影响已冻结的重放结果
        motherLiquors.updateRemaining(f.motherId, 100.0, T0.getEpochSecond());
        ChangeService.ChangeResult afterMotherChange = changeService.submit(requestId, f.dispensingId, 1L,
                NEW_ADMIN_EPOCH);
        assertThat(afterMotherChange.replayed()).isTrue();
        assertThat(afterMotherChange.change().recomputedActivityBq()).isEqualTo(RECOMPUTED);
    }

    @Test
    void reviewIdempotencyAndSeparatorInReviewerName() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        // 合法文本含分隔符 '|' 的复核人可正常复核
        String requestId = unique("REQ");
        ChangeService.ReviewResult first = changeService.review(requestId, changeId, "carol|night-shift");
        assertThat(first.change().firstReviewer()).isEqualTo("carol|night-shift");
        // 同键同参重放：返回首次冻结结果
        ChangeService.ReviewResult replay = changeService.review(requestId, changeId, "carol|night-shift");
        assertThat(replay.replayed()).isTrue();
        assertThat(replay.review().resultingStatus()).isEqualTo(ChangeStatus.PENDING);
        // 同键异参（含分隔符前缀相同的不同复核人）→ 409
        assertThatThrownBy(() -> changeService.review(requestId, changeId, "carol"))
                .isInstanceOf(ConflictException.class);
    }

    @Test
    void voidChangeOnlyWhilePending() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        String voidRequest = unique("REQ");
        ChangeService.ChangeResult voided = changeService.voidChange(voidRequest, changeId);
        assertThat(voided.change().status()).isEqualTo(ChangeStatus.VOIDED);
        // 同键重放
        assertThat(changeService.voidChange(voidRequest, changeId).replayed()).isTrue();
        // 异键重复作废 → 422；已作废禁止复核 → 422
        assertThatThrownBy(() -> changeService.voidChange(unique("REQ"), changeId))
                .isInstanceOf(BusinessException.class);
        assertThatThrownBy(() -> changeService.review(unique("REQ"), changeId, "carol"))
                .isInstanceOf(BusinessException.class);
        // 作废后分装未受影响，仍可正常发药流程
        Dispensing dispensing = dispensings.findDispensingById(f.dispensingId).orElseThrow();
        assertThat(dispensing.status()).isEqualTo(DispensingStatus.CHECKED);
        assertThat(dispensing.version()).isEqualTo(1);
    }

    @Test
    void approvedChangeCannotBeVoidedAndTerminalChangeCannotBeReviewed() {
        Fixture f = newCheckedFixture();
        long changeId = changeService.submit(unique("REQ"), f.dispensingId, 1L, NEW_ADMIN_EPOCH)
                .change().id();
        changeService.review(unique("REQ"), changeId, "carol");
        changeService.review(unique("REQ"), changeId, "dave");
        assertThatThrownBy(() -> changeService.voidChange(unique("REQ"), changeId))
                .isInstanceOf(BusinessException.class);
        assertThatThrownBy(() -> changeService.review(unique("REQ"), changeId, "ellen"))
                .isInstanceOf(BusinessException.class);
    }

    /** 构造母液 2200 Bq@T0、处方 550 Bq@T0+7200、已完成双人核对的批次夹具。 */
    private Fixture newCheckedFixture() {
        long calibratorId = registrationService.registerCalibrator(unique("CAL"), "合成活度计");
        calibratorService.dailyCheck(unique("REQ"), calibratorId, CHECK_DATE, 1000.0, 1000.0);
        MotherLiquor mother = registrationService.registerMotherLiquor(unique("ML"), "SYN-1H",
                2200.0, T0.getEpochSecond());
        Prescription prescription = registrationService.registerPrescription(unique("RX"), "SYN-1H",
                550.0, ADMIN_EPOCH);
        Dispensing d = dispensingService.calculate(unique("REQ"), mother.id(), prescription.id(), calibratorId);
        assertThat(d.dispensedActivityBq()).isEqualTo(550.0);
        dispensingService.check(d.id(), "alice");
        dispensingService.check(d.id(), "bob");
        return new Fixture(mother.id(), prescription.id(), calibratorId, d.id());
    }

    private record Fixture(long motherId, long prescriptionId, long calibratorId, long dispensingId) {
    }
}

