package com.example.starter.radio.service;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

/**
 * 结构化幂等指纹：长度前缀编码无歧义，合法文本含分隔符也须区分。
 */
class FingerprintsTest {

    @Test
    void structuredFingerprintDistinguishesSeparatorInText() {
        // 朴素分隔符连接会碰撞的输入，结构化编码必须区分
        assertThat(Fingerprints.structured("a|b", "c"))
                .isNotEqualTo(Fingerprints.structured("a", "b|c"));
        assertThat(Fingerprints.structured("a|b", "c"))
                .isNotEqualTo(Fingerprints.structured("a", "b", "c"));
        assertThat(Fingerprints.structured("1", "23"))
                .isNotEqualTo(Fingerprints.structured("12", "3"));
        assertThat(Fingerprints.structured("x:y;", "z"))
                .isNotEqualTo(Fingerprints.structured("x", "y:z;"));
    }

    @Test
    void structuredFingerprintIsStableAndHandlesNull() {
        assertThat(Fingerprints.structured("REQ-1", 7L, 2, 7000L))
                .isEqualTo(Fingerprints.structured("REQ-1", 7L, 2, 7000L));
        assertThat(Fingerprints.structured("REQ-1", 7L, 2, 7000L))
                .isNotEqualTo(Fingerprints.structured("REQ-1", 7L, 2, 7001L));
        // null 与空串、缺失字段均可区分
        assertThat(Fingerprints.structured("a", (Object) null))
                .isNotEqualTo(Fingerprints.structured("a", ""));
        assertThat(Fingerprints.structured("a", (Object) null))
                .isNotEqualTo(Fingerprints.structured("a"));
    }
}

