}

/**
 * 给药时刻变更复核 HTTP 主流程与错误语义。
 * 母液 2200 Bq@T0，处方 550 Bq@T0+2h（偏差 0）；新给药时刻 T0+7000s 重算约 571.59 Bq，合法。
 */
@Test
void changeFlowOverHttp() throws Exception {
    long calibratorId = postAndGetId("/api/calibrators",
            "{\"code\":\"CAL-API-2\",\"name\":\"合成活度计\"}");
    mvc.perform(post("/api/calibrators/daily-check").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-CHK-2\",\"calibratorId\":" + calibratorId
                            + ",\"checkDate\":\"2026-09-26\",\"referenceActivityBq\":1000.0,"
                            + "\"measuredActivityBq\":1000.0}"))
            .andExpect(status().isOk());
    long motherId = postAndGetId("/api/mother-liquors",
            "{\"batchCode\":\"ML-API-2\",\"nuclideCode\":\"SYN-1H\",\"initialActivityBq\":2200.0,"
                    + "\"referenceTime\":\"2026-09-26T00:00:00Z\"}");
    long prescriptionId = postAndGetId("/api/prescriptions",
            "{\"code\":\"RX-API-2\",\"nuclideCode\":\"SYN-1H\",\"prescribedActivityBq\":550.0,"
                    + "\"administrationTime\":\"2026-09-26T02:00:00Z\"}");
    long dispensingId = postAndGetId("/api/dispensings/calculate",
            "{\"requestId\":\"REQ-CALC-2\",\"motherLiquorId\":" + motherId
                    + ",\"prescriptionId\":" + prescriptionId + ",\"calibratorId\":" + calibratorId + "}");
    mvc.perform(post("/api/dispensings/{id}/checks", dispensingId)
                    .contentType(MediaType.APPLICATION_JSON).content("{\"checker\":\"alice\"}"))
            .andExpect(status().isOk());
    mvc.perform(post("/api/dispensings/{id}/checks", dispensingId)
                    .contentType(MediaType.APPLICATION_JSON).content("{\"checker\":\"bob\"}"))
            .andExpect(status().isOk());

    // 参数非法 → 400（缺 expectedVersion）
    mvc.perform(post("/api/changes").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-CHG-0\",\"dispensingId\":" + dispensingId + "}"))
            .andExpect(status().isBadRequest());
    // 对象不存在 → 404
    mvc.perform(post("/api/changes").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-CHG-0\",\"dispensingId\":999999,"
                            + "\"expectedVersion\":1,\"newAdministrationTime\":\"2026-09-26T01:56:40Z\"}"))
            .andExpect(status().isNotFound());
    // expectedVersion 与当前版本不一致 → 409
    mvc.perform(post("/api/changes").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-CHG-0\",\"dispensingId\":" + dispensingId
                            + ",\"expectedVersion\":2,\"newAdministrationTime\":\"2026-09-26T01:56:40Z\"}"))
            .andExpect(status().isConflict());
    // 候选超出 ±10% 偏差（T0+1h 重算 1100 Bq）→ 422
    mvc.perform(post("/api/changes").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-CHG-0\",\"dispensingId\":" + dispensingId
                            + ",\"expectedVersion\":1,\"newAdministrationTime\":\"2026-09-26T01:00:00Z\"}"))
            .andExpect(status().isUnprocessableEntity());

    // 合法提交（T0+7000s = 2026-09-26T01:56:40Z）→ 200 PENDING；同键重放；同键异参 → 409
    long changeId = postAndGetId("/api/changes",
            "{\"requestId\":\"REQ-CHG-1\",\"dispensingId\":" + dispensingId
                    + ",\"expectedVersion\":1,\"newAdministrationTime\":\"2026-09-26T01:56:40Z\"}");
    mvc.perform(post("/api/changes").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-CHG-1\",\"dispensingId\":" + dispensingId
                            + ",\"expectedVersion\":1,\"newAdministrationTime\":\"2026-09-26T01:56:40Z\"}"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.id").value(changeId))
            .andExpect(jsonPath("$.replayed").value(true))
            .andExpect(jsonPath("$.status").value("PENDING"));
    mvc.perform(post("/api/changes").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-CHG-1\",\"dispensingId\":" + dispensingId
                            + ",\"expectedVersion\":1,\"newAdministrationTime\":\"2026-09-26T01:58:20Z\"}"))
            .andExpect(status().isConflict());

    // 双人复核：同一人第二次 → 409；两名不同人员 → APPROVED
    mvc.perform(post("/api/changes/{id}/reviews", changeId).contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-REV-1\",\"reviewer\":\"carol\"}"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.resultingStatus").value("PENDING"));
    mvc.perform(post("/api/changes/{id}/reviews", changeId).contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-REV-2\",\"reviewer\":\"carol\"}"))
            .andExpect(status().isConflict());
    mvc.perform(post("/api/changes/{id}/reviews", changeId).contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-REV-3\",\"reviewer\":\"dave\"}"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.resultingStatus").value("APPROVED"))
            .andExpect(jsonPath("$.status").value("APPROVED"));

    // 生效后：版本 2、新给药时刻、旧签认失效；旧签认不得复用，直接发药 → 422
    mvc.perform(get("/api/dispensings/{id}", dispensingId))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.version").value(2))
            .andExpect(jsonPath("$.administrationTime").value("2026-09-26T01:56:40Z"))
            .andExpect(jsonPath("$.status").value("CALCULATED"))
            .andExpect(jsonPath("$.firstChecker").doesNotExist());
    mvc.perform(post("/api/dispensings/dispense").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-DISP-9\",\"dispensingId\":" + dispensingId
                            + ",\"remainingActivityBq\":0.0,\"measuredAt\":\"2026-09-26T01:56:40Z\"}"))
            .andExpect(status().isUnprocessableEntity());

    // 版本计算证据：v1 保留旧计算与 alice/bob 签认，v2 来自变更单
    mvc.perform(get("/api/dispensings/{id}/versions", dispensingId))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.length()").value(2))
            .andExpect(jsonPath("$[0].version").value(1))
            .andExpect(jsonPath("$[0].dispensedActivityBq").value(550.0))
            .andExpect(jsonPath("$[0].firstChecker").value("alice"))
            .andExpect(jsonPath("$[1].version").value(2))
            .andExpect(jsonPath("$[1].changeId").value(changeId));
    // 变更单详情含双人复核链
    mvc.perform(get("/api/changes/{id}", changeId))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.status").value("APPROVED"))
            .andExpect(jsonPath("$.reviews.length()").value(2));
    // 已生效不可作废 → 422；变更单不存在 → 404
    mvc.perform(post("/api/changes/{id}/void", changeId).contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-VOID-1\"}"))
            .andExpect(status().isUnprocessableEntity());
    mvc.perform(get("/api/changes/{id}", 999999))
            .andExpect(status().isNotFound());

    // 重新双人核对新版本后发药成功（2200 = 571.59 + 0 + 衰变残量）
    mvc.perform(post("/api/dispensings/{id}/checks", dispensingId)
                    .contentType(MediaType.APPLICATION_JSON).content("{\"checker\":\"alice\"}"))
            .andExpect(status().isOk());
    mvc.perform(post("/api/dispensings/{id}/checks", dispensingId)
                    .contentType(MediaType.APPLICATION_JSON).content("{\"checker\":\"bob\"}"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.status").value("CHECKED"));
    mvc.perform(post("/api/dispensings/dispense").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-DISP-10\",\"dispensingId\":" + dispensingId
                            + ",\"remainingActivityBq\":0.0,\"measuredAt\":\"2026-09-26T01:56:40Z\"}"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.status").value("DISPENSED"))
            .andExpect(jsonPath("$.ledger.balanced").value(true));
    // 已发药历史绝不重开 → 422
    mvc.perform(post("/api/changes").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"requestId\":\"REQ-CHG-9\",\"dispensingId\":" + dispensingId
                            + ",\"expectedVersion\":2,\"newAdministrationTime\":\"2026-09-26T01:58:20Z\"}"))
            .andExpect(status().isUnprocessableEntity());
}

